void process_hid_field_input(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
    int i;
    int *values;

    if (!field->report_count)
        return;

    values = kmalloc(field->report_count * sizeof(int), GFP_KERNEL);
    if (!values)
        return;

    for (i = 0; i < field->report_count; i++) {
        int value;
        int logical_max = field->logical_max;

        if (logical_max == 0)
            logical_max = 1;

        value = hid_field_extract_value(field, i, data);
        if (value < 0)
            continue;

        values[i] = value;

        if (field->logical_min <= value && value <= field->logical_max) {
            hid_process_event(hid, field->usage[i].hid, value, interrupt);
        }
    }

    for (i = 0; i < field->maxusage; i++) {
        field->value[i] = values[i];
    }

    kfree(values);
}

void process_hid_device_field(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
    int i;
    int j;
    int *values = kmalloc(field->report_count * sizeof(int), GFP_KERNEL);

    for (i = 0; i < field->report_count; i++) {
        int value = hid->ll_driver->get_value(hid, field, i, 0, 0);

        if (value >= field->logical_minimum && value <= field->logical_maximum) {
            hid_process_event(hid, field->usage->hid, value, interrupt);
        }

        values[i] = value;
    }

    for (j = 0; j < field->report_count; j++) {
        field->value[j] = values[j];
    }

    kfree(values);
}

void process_hid_field(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
    int i, j, offset = 0;
    __s32 *values = kmalloc(field->report_count * sizeof(__s32), GFP_KERNEL);

    if (!values)
        return;

    for (i = 0; i < field->report_count; i++) {
        __s32 value = 0;

        for (j = 0; j < field->maxusage; j++) {
            struct hid_usage *usage = &field->usage[j];

            if (usage->hat || (usage->type != HID_DT_VALUE))
                continue;

            if (field->logical_minimum > value)
                value = field->logical_minimum;
            if (field->logical_maximum < value)
                value = field->logical_maximum;

            hid_process_event(usage, value, field->hidinput);
        }

        field->value[i] = value;
        offset += field->report_size;
    }

    memcpy(field->value, values, field->report_count * sizeof(__s32));
    kfree(values);
}

void process_hid_field(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
    int *values;
    int i;

    values = kmalloc(field->report_count * sizeof(int), GFP_ATOMIC);
    if (!values)
        return;

    for (i = 0; i < field->report_count; i++) {
        int value = hid->driver->report_field_value(hid, field, i, data);
        if (value < field->logical_minimum || value > field->logical_maximum)
            continue;

        if (field->flags & HID_MAIN_ITEM_REL) {
            hid->grabbed = 1;
            hid->rel_axes[i] += value;
        }

        hid_process_event(hid, field->usage->hid, value, interrupt);
    }

    for (i = 0; i < field->report_count; i++)
        field->value[i] = values[i];

    kfree(values);
}

void process_hid_field(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
    int i, j;
    int *values = kmalloc(field->report_count * sizeof(int), GFP_KERNEL);
    if (!values)
        return;

    for (i = 0; i < field->report_count; i++) {
        __s32 value = hid->driver->hid_input_fetch(field, i, data);
        if (value < field->logical_minimum || value > field->logical_maximum)
            continue;

        values[i] = value;
        if (field->flags & HID_MAIN_ITEM_CONSTANT)
            continue;

        if (interrupt)
            hid_process_event(hid, field->usage->hid, values[i], field->usage);

        for (j = 0; j < field->maxusage; j++) {
            if (field->usage[j].hid != field->usage->hid)
                continue;

            field->value[j] = values[i];
            break;
        }
    }

    kfree(values);
}
